begin;
set local statement_timeout='40s';set local lock_timeout='5s';
create temporary table commerce_probe(a uuid,b uuid,c uuid,admin uuid,conversation uuid,message uuid,campaign uuid,live uuid,client uuid) on commit drop;
insert into commerce_probe values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),null,null,null,gen_random_uuid());
grant all on commerce_probe to authenticated,service_role;
insert into public.users(id,email) select id,'commerce-probe-'||id||'@example.invalid' from(select a id from commerce_probe union all select b from commerce_probe union all select c from commerce_probe union all select admin from commerce_probe)x;
insert into public.profiles(user_id,display_name,onboarding_completed,discoverable) select id,'Commerce probe',true,true from(select a id from commerce_probe union all select b from commerce_probe union all select c from commerce_probe union all select admin from commerce_probe)x;
insert into public.user_sessions(user_id,auth_session_id) select a,'commerce-a' from commerce_probe union all select b,'commerce-b' from commerce_probe union all select c,'commerce-c' from commerce_probe;
insert into public.connections(user_a,user_b) select least(a,b),greatest(a,b) from commerce_probe;
insert into public.user_roles(user_id,role) select admin,'admin' from commerce_probe;
insert into public.conversations(id,direct_a,direct_b) select conversation,least(a,b),greatest(a,b) from commerce_probe;
insert into public.conversation_members(conversation_id,user_id) select conversation,a from commerce_probe union all select conversation,b from commerce_probe;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id','commerce-a')::text,true) from commerce_probe;
set local role authenticated;
do $$declare r jsonb;begin
 r:=public.sidle_platform('messages.send',jsonb_build_object('conversationId',(select conversation from pg_temp.commerce_probe),'clientId',(select client from pg_temp.commerce_probe),'body','Synthetic message'));
 update pg_temp.commerce_probe set message=(r->>'id')::uuid;
 if r is distinct from public.sidle_platform('messages.send',jsonb_build_object('conversationId',(select conversation from pg_temp.commerce_probe),'clientId',(select client from pg_temp.commerce_probe),'body','Synthetic message')) then raise exception 'Message retry duplicated';end if;
 perform public.sidle_platform('messages.edit',jsonb_build_object('id',r->>'id','body','Edited synthetic message'));
 if public.sidle_platform('messages.details',jsonb_build_object('ids',jsonb_build_array(r->>'id')))->0->>'editedAt' is null then raise exception 'Edit metadata missing';end if;
 perform public.sidle_platform('messages.send',jsonb_build_object('conversationId',(select conversation from pg_temp.commerce_probe),'clientId',gen_random_uuid(),'body','Synthetic reply','replyTo',(select message from pg_temp.commerce_probe)));
 begin perform public.sidle_billing_event('{}');raise exception 'Client credit forgery';exception when insufficient_privilege then null;end;
 r:=public.sidle_platform('ads.create','{"title":"Synthetic ad","body":"Test campaign","targetUrl":"https://example.invalid/","budget":20}');update pg_temp.commerce_probe set campaign=(r->>'id')::uuid;
 r:=public.sidle_platform('live.create','{"title":"Synthetic broadcast","audience":"connections"}');update pg_temp.commerce_probe set live=(r->>'id')::uuid;
 if public.sidle_platform('live.join',jsonb_build_object('id',r->>'id'))->>'owner'<>'true' then raise exception 'Host publishing permission';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated','session_id','commerce-c')::text,true) from commerce_probe;
set local role authenticated;
do $$begin
 if public.sidle_platform('messages.details',jsonb_build_object('ids',jsonb_build_array((select message from pg_temp.commerce_probe))))<>'[]'::jsonb then raise exception 'Outsider message metadata leak';end if;
 begin perform public.sidle_platform('messages.react',jsonb_build_object('id',(select message from pg_temp.commerce_probe),'reaction','love'));raise exception 'Outsider reaction';exception when insufficient_privilege then null;end;
 begin perform public.sidle_platform('live.join',jsonb_build_object('id',(select live from pg_temp.commerce_probe)));raise exception 'Outsider live grant';exception when insufficient_privilege then null;end;
end;$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id','commerce-b')::text,true) from commerce_probe;
set local role authenticated;
do $$begin
 perform public.sidle_platform('messages.react',jsonb_build_object('id',(select message from pg_temp.commerce_probe),'reaction','love'));
 if public.sidle_platform('messages.details',jsonb_build_object('ids',jsonb_build_array((select message from pg_temp.commerce_probe))))->0->'reactions'->0->>'count'<>'1' then raise exception 'Reaction count';end if;
 begin perform public.sidle_platform('messages.edit',jsonb_build_object('id',(select message from pg_temp.commerce_probe),'body','Forged edit'));raise exception 'Foreign edit accepted';exception when insufficient_privilege then null;end;
 if public.sidle_platform('live.join',jsonb_build_object('id',(select live from pg_temp.commerce_probe)))->>'owner'<>'false' then raise exception 'Viewer publishing grant';end if;
 if public.sidle_platform('ads.serve','{}')<>'[]'::jsonb then raise exception 'Unapproved ad delivered';end if;
end;$$;
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',admin,'role','authenticated','session_id','commerce-admin')::text,true) from commerce_probe;
set local role authenticated;
select public.sidle_platform('admin.settings','{"advertisingEnabled":true}');
select public.sidle_platform('admin.ad.review',jsonb_build_object('id',campaign,'status','approved')) from commerce_probe;
reset role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
do $$declare payload jsonb;begin
 if public.sidle_live_access((select live from pg_temp.commerce_probe),(select a from pg_temp.commerce_probe),'commerce-a')->>'allowed'<>'true' then raise exception 'Host service access';end if;
 if public.sidle_live_access((select live from pg_temp.commerce_probe),(select c from pg_temp.commerce_probe),'commerce-c')->>'allowed'<>'false' then raise exception 'Outsider service access';end if;
 perform public.sidle_live_access(null,null,null,true);
 if public.sidle_live_access((select live from pg_temp.commerce_probe),(select a from pg_temp.commerce_probe),'commerce-a')->>'guardReady'<>'true' then raise exception 'Live guard heartbeat';end if;
 payload:=jsonb_build_object('eventId','evt_'||(select client from pg_temp.commerce_probe),'kind','paid','userId',(select a from pg_temp.commerce_probe),'sessionId','cs_'||(select client from pg_temp.commerce_probe),'paymentId','pi_'||(select client from pg_temp.commerce_probe),'customerId','cus_'||(select client from pg_temp.commerce_probe),'purpose','ad_credit','credits',10,'amount',100,'currency','usd');
 perform public.sidle_billing_event(payload);if public.sidle_billing_event(payload)->>'duplicate'<>'true' then raise exception 'Duplicate webhook not detected';end if;
 perform public.sidle_billing_event(payload||jsonb_build_object('eventId','evt_duplicate_session_'||(select client from pg_temp.commerce_probe)));
end;$$;
reset role;

do $$begin if(select balance from app_private.ad_wallets where user_id=(select a from commerce_probe))<>10 then raise exception 'Payment credited twice';end if;end;$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id','commerce-b')::text,true) from commerce_probe;
set local role authenticated;
do $$begin
 if jsonb_array_length(public.sidle_platform('ads.serve','{}'))<1 then raise exception 'Funded approved ad absent';end if;
 perform public.sidle_platform('ads.click',jsonb_build_object('id',(select campaign from pg_temp.commerce_probe)));
 perform public.sidle_platform('ads.click',jsonb_build_object('id',(select campaign from pg_temp.commerce_probe)));
end;$$;
reset role;
do $$begin if(select balance from app_private.ad_wallets where user_id=(select a from commerce_probe))<>9 then raise exception 'Duplicate daily click charged';end if;end;$$;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
set local role service_role;
select public.sidle_billing_event(jsonb_build_object('eventId','evt_refund_'||client,'kind','refund','paymentId','pi_'||client,'refundedAmount',100)) from commerce_probe;
select public.sidle_platform_retention();select public.sidle_media_cleanup_batch();
reset role;
do $$begin if(select debt from app_private.ad_wallets where user_id=(select a from commerce_probe))<>1 then raise exception 'Spent-credit refund debt';end if;if(select status from app_private.ad_campaigns where id=(select campaign from commerce_probe))<>'paused' then raise exception 'Refund did not pause campaign';end if;end;$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id','commerce-a')::text,true) from commerce_probe;
set local role authenticated;
select public.sidle_platform('messages.delete',jsonb_build_object('id',message)) from commerce_probe;
select public.sidle_platform('live.end',jsonb_build_object('id',live)) from commerce_probe;
reset role;
do $$begin if(select body from public.messages where id=(select message from commerce_probe))<>'[Message removed]' then raise exception 'Deletion tombstone';end if;end;$$;
rollback;
select 'PASS: rich messaging retry/reply/edit/reactions/delete and membership, service-only payments, duplicate session/event accounting, ad approval/funding/click deduplication/refund debt, live host/viewer/outsider grants and retention; fixtures rolled back' as result;
